import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { chromium } from 'playwright-core';
const out = process.env.TRADING_EVIDENCE_DIR;
const browser = await chromium.connectOverCDP(process.env.TRADING_CDP_URL);
const page = browser.contexts()[0].pages().find(p => p.url().includes('/trading-proof'));
page.setDefaultTimeout(15000);
const results = { views: [], checks: [], errors: [] };
page.on('pageerror', e => results.errors.push(e.message));
const panel = () => page.locator('[data-panel-id]:visible').filter({ has: page.locator('[data-side="buy"]') }).first();
const ticket = () => panel().getByRole('region', { name: 'Trade', exact: true });
const amount = () => ticket().locator('[data-panel-amount]');
const open = async () => { await page.waitForFunction(() => Object.keys(document.querySelector('#trading-open') ?? {}).some(k => k.startsWith('__reactProps'))); await page.waitForTimeout(300); if (!await page.locator('[data-workspace-host]').count()) await page.locator('#trading-open').click(); await page.waitForFunction(() => !!window.tradingFixture); await page.evaluate(() => { window.tradingFixture.store.setPresentation('focus'); window.tradingFixture.store.focus('A'); }); await panel().waitFor(); };
const focusExit = () => page.getByRole('button', { name: 'Exit Esc', exact: true }).focus();
const press = key => page.keyboard.press(key);
const closed = () => page.waitForFunction(() => !document.querySelector('[role="dialog"]'));
const sheet = () => page.getByRole('dialog');
try {
  await page.setViewportSize({ width: 1414, height: 1000 });
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.evaluate(() => localStorage.removeItem('blast.workspace.trade-presets.v1'));
  await page.goto('http://127.0.0.1:42874/trading-proof');
  await open(); await focusExit(); await press('Escape');
  await page.locator('#trading-open').waitFor();
  await press('f'); await press('b');
  assert.equal(await panel().count(), 0);
  await open(); await focusExit(); await press('b'); await panel().waitFor({ state: 'detached' });
  await open(); await focusExit();
  await press('q'); await press('1'); assert.equal(await amount().inputValue(), '50');
  await page.waitForFunction(() => !document.querySelector('[data-panel-id="A"] [data-coin-submit]')?.disabled);
  await page.keyboard.down('Shift'); await page.keyboard.down('Space'); await sheet().waitFor(); assert.match(await sheet().innerText(), /Buy|Review/);
  await page.keyboard.down('Space'); await page.keyboard.down('Space'); await page.keyboard.up('Space'); await page.keyboard.up('Shift'); assert.equal(await sheet().count(), 1, 'held submit repeats cannot activate a dialog button');
  await press('Shift+Space'); assert.equal(await sheet().count(), 1);
  await press('Escape'); await closed(); assert.equal(await panel().count(), 1);
  await focusExit(); await press('e'); await press('3'); assert.equal(await amount().inputValue(), '450,000');
  await press('4'); assert.equal(await amount().inputValue(), '600,000');
  await amount().fill('12'); await press('3'); assert.equal(await amount().inputValue(), '123');
  await press('Enter'); assert.equal(await sheet().count(), 0);
  await page.waitForFunction(() => !document.querySelector('[data-panel-id="A"] [data-coin-submit]')?.disabled);
  await press('Shift+Space'); await sheet().waitFor(); assert.match(await sheet().innerText(), /Sell/); await press('Escape'); await closed();
  results.checks.push('B/F leave the closed workspace alone, B exits, Q/E + 1–4 sequence, plain digits/Enter, Shift+Space confirmation from button and input, Esc closes layer first');
  await ticket().getByRole('button', { name: 'Edit amount presets' }).click();
  await sheet().getByLabel('Buy preset 1', { exact: true }).fill('11.25');
  await sheet().getByLabel('Buy preset 2', { exact: true }).fill('22.50');
  await sheet().getByLabel('Sell preset 1', { exact: true }).fill('12.34');
  await sheet().getByLabel('Sell preset 4', { exact: true }).fill('101');
  assert.equal(await sheet().getByRole('button', { name: 'Save presets' }).isDisabled(), true);
  await sheet().getByLabel('Sell preset 4', { exact: true }).fill('100');
  await sheet().getByRole('button', { name: 'Save presets' }).click(); await closed(); assert.equal(await amount().inputValue(), '123');
  await focusExit(); await press('q'); await press('1'); assert.equal(await amount().inputValue(), '11.25');
  await press('2'); assert.equal(await amount().inputValue(), '22.50');
  await press('e'); await press('1'); assert.equal(await amount().inputValue(), '74,040');
  await ticket().getByRole('button', { name: 'Edit amount presets' }).click();
  await sheet().getByLabel('Buy preset 1', { exact: true }).fill('99'); await press('Escape'); await closed();
  await focusExit(); await press('q'); await press('1'); assert.equal(await amount().inputValue(), '11.25');
  await page.reload(); await open(); await focusExit(); await press('q'); await press('1'); assert.equal(await amount().inputValue(), '11.25');
  results.checks.push('custom buy/sell values, range validation, unchanged draft on save, cancellation, reload persistence');
  await ticket().getByRole('button', { name: 'Edit amount presets' }).click();
  await sheet().getByLabel('Buy preset 1', { exact: true }).fill('88');
  await page.evaluate(() => { window.presetSetItem = Storage.prototype.setItem; Storage.prototype.setItem = function(key, value) { if (key === 'blast.workspace.trade-presets.v1') throw new Error('Simulated storage failure'); return window.presetSetItem.call(this, key, value); }; });
  await sheet().getByRole('button', { name: 'Save presets' }).click(); assert.match(await sheet().getByRole('alert').innerText(), /Couldn’t save/);
  await page.evaluate(() => { Storage.prototype.setItem = window.presetSetItem; }); await press('Escape'); await closed();
  assert.equal(await ticket().locator('[data-trade-preset="1"]').innerText(), '$11.25');
  results.checks.push('storage write failure retains existing preferences and edited values for retry');
  const cdp = await page.context().newCDPSession(page);
  for (const theme of ['light', 'dark']) for (const width of [320, 407, 768, 1054, 1414]) {
    await page.setViewportSize({ width, height: 1000 }); await cdp.send('Emulation.setTouchEmulationEnabled', { enabled: width < 1024, maxTouchPoints: 1 });
    await page.evaluate(t => document.querySelector('[data-blast-ui]').setAttribute('data-theme', t), theme);
    await ticket().getByRole('button', { name: 'Edit amount presets' }).scrollIntoViewIfNeeded();
    await page.waitForTimeout(180);
    const geometry = await ticket().evaluate(e => ({ width: innerWidth, document: document.documentElement.scrollWidth, ticket: e.getBoundingClientRect().toJSON(), controls: [...e.querySelectorAll('[data-trade-preset],button[aria-label="Edit amount presets"]')].map(b => ({ text: b.textContent || b.getAttribute('aria-label'), ...b.getBoundingClientRect().toJSON() })) }));
    assert.ok(geometry.document <= width, JSON.stringify(geometry));
    for (const control of geometry.controls) { assert.ok(control.left >= geometry.ticket.left - 1 && control.right <= geometry.ticket.right + 1, JSON.stringify(geometry)); if (width < 1024) assert.ok(control.width >= 44 && control.height >= 44, JSON.stringify(control)); }
    await page.screenshot({ path: `${out}/ticket-${theme}-${width}.png` });
    await ticket().getByRole('button', { name: 'Edit amount presets' }).click();
    assert.equal(await sheet().getByLabel('Buy preset 1', { exact: true }).inputValue(), '11.25');
    assert.equal(await sheet().evaluate(e => e.scrollWidth <= e.clientWidth + 1), true);
    assert.equal(await sheet().getByText('Preset 1', { exact: true }).count(), 2);
    assert.equal(await sheet().getByRole('button', { name: 'Save presets' }).evaluate(e => getComputedStyle(e).backgroundColor), theme === 'light' ? 'rgb(214, 27, 112)' : 'rgb(255, 76, 152)');
    await page.screenshot({ path: `${out}/presets-${theme}-${width}.png` });
    await press('Escape'); await closed();
    assert.equal(await ticket().getByRole('button', { name: 'Edit amount presets' }).evaluate(e => e === document.activeElement), true);
    results.views.push({ theme, ...geometry });
  }
  await page.setViewportSize({ width: 1414, height: 1000 }); await cdp.send('Emulation.setTouchEmulationEnabled', { enabled: false });
  await focusExit(); await press('?'); await sheet().waitFor(); assert.match(await sheet().innerText(), /Shift/); await page.screenshot({ path: `${out}/shortcuts-dark.png` }); await press('Escape'); await closed();
  await ticket().getByRole('button', { name: 'Edit amount presets' }).click(); await sheet().getByRole('button', { name: 'Reset defaults' }).click(); await sheet().getByRole('button', { name: 'Save presets' }).click(); await closed();
  assert.equal(await ticket().locator('[data-trade-preset="1"]').innerText(), '$50');
  results.checks.push('five widths, both themes, touch targets, dialog focus return, shortcut help, restore defaults');
  assert.deepEqual(results.errors, []);
  writeFileSync(`${out}/verification.json`, JSON.stringify(results, null, 2));
  console.log('PASS shortcuts, confirmation, editable presets, storage/cancel/reload, five widths and both themes');
} catch (error) { await page.screenshot({ path: `${out}/failure.png` }); writeFileSync(`${out}/progress.json`, JSON.stringify(results, null, 2)); throw error; }
finally { await browser.close(); }
